activities.codeSnippet:
public class Main {
    public static void main(String[] args) {
        // Primitive types (Direct values)
        int studentAge = 20;
        double studentCgpa = 8.75;
        char divisionGrade = 'A';
        boolean isFeePaid = true;

        // Reference type (Points to text object in memory)
        String studentName = "Priya Sharma";

        System.out.println("Student: " + studentName);
        System.out.println("Age: " + studentAge);
        System.out.println("CGPA: " + studentCgpa);
        System.out.println("Grade: " + divisionGrade);
        System.out.println("Fee Cleared: " + isFeePaid);
    }
}

