practice.solutionCode:
public class Main {
    public static void main(String[] args) {
        int studentRoll = 101;
        double semesterCgpa = 8.85;
        boolean isFeePaid = true;

        System.out.println("Roll: " + studentRoll + " | CGPA: " + semesterCgpa + " | Fee Paid: " + isFeePaid);
    }
}

